import math
from collections.abc import Mapping
from numbers import Real


def aggregate_metrics(events):
    if isinstance(events, (str, bytes)):
        raise TypeError("events must be a non-string iterable")
    try:
        items = list(events)
    except TypeError as exc:
        raise TypeError("events must be iterable") from exc
    validated = []
    for event in items:
        if not isinstance(event, Mapping):
            raise TypeError("each event must be a mapping")
        if set(event) != {"category", "amount", "accepted"}:
            raise ValueError("event contains missing or unexpected keys")
        category = event["category"]
        amount = event["amount"]
        accepted = event["accepted"]
        if not isinstance(category, str):
            raise TypeError("category must be a string")
        if not category:
            raise ValueError("category cannot be empty")
        if not isinstance(amount, Real) or isinstance(amount, bool):
            raise TypeError("amount must be a real number")
        if not math.isfinite(float(amount)):
            raise ValueError("amount must be finite")
        if type(accepted) is not bool:
            raise TypeError("accepted must be a boolean")
        validated.append((category, amount, accepted))
    totals = {}
    for category, amount, accepted in validated:
        if accepted:
            continue
        if category not in totals:
            totals[category] = [0, 0]
        totals[category][0] += 1
        totals[category][1] += amount
    return [
        {"category": category, "count": values[0], "total": values[1]}
        for category, values in totals.items()
    ]
```

